func TestAgyHelperProcess(t *testing.T) {
	if os.Getenv("GO_WANT_AGY_HELPER") != "1" {
		return
	}
	separator := slices.Index(os.Args, "--")
	args := os.Args[separator+1:]
	if len(args) == 1 && args[0] == "--version" {
		version := os.Getenv("AGY_HELPER_VERSION")
		if version == "" {
			version = "1.1.15"
		}
		fmt.Println(version)
		os.Exit(0)
	}
	if record := os.Getenv("AGY_HELPER_RECORD"); record != "" {
		file, err := os.OpenFile(record, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
		if err != nil {
			os.Exit(2)
		}
		_ = json.NewEncoder(file).Encode(args)
		_ = file.Close()
	}
	sessionID := flagValue(args, "--conversation")
	if sessionID == "" {
		sessionID = "conversation-test"
	}
	mode := os.Getenv("AGY_HELPER_MODE")
	if mode == "internal" {
		writeJSON(map[string]any{"event": "result", "result": map[string]any{
			"status": "ERROR", "error": "Eligibility check failed: INTERNAL (code 500): We can't connect to Gemini Code Assist",
		}})
		os.Exit(1)
	}
	prompt := flagValue(args, "-p")
	if mode == "artifact_recover" || mode == "artifact_persist" {
		repaired := strings.Contains(prompt, "shell/terminal tool")
		if mode == "artifact_persist" || !repaired {
			writeJSON(map[string]any{"event": "result", "result": map[string]any{
				"status": "ERROR", "error": "declaring permissions: cortex tool write_to_file: convert tool call for permissions: model output error: invalid tool call error (invalid_args) /workdir/gemini_proposal.md is not a valid artifact path; artifacts must be in /Users/tyler/.gemini/antigravity-cli/brain/56536675-0470-4bfc-b8ee-a04946debce9/",
			}})
			os.Exit(1)
		}
	}
	if mode == "hook_deny_recover" || mode == "hook_deny_persist" {
		repaired := strings.Contains(prompt, "shell/terminal tool")
		if mode == "hook_deny_persist" || !repaired {
			writeJSON(map[string]any{"event": "result", "result": map[string]any{
				"status": "ERROR", "error": "tool call denied by pre-tool hook: " + nativeWriteHookMarker + " Native write_to_file, replace_file_content, and multi_replace_file_content are disabled: agy fails the whole turn when their target lies outside the private brain/<uuid> directory even though the physical write already succeeded. Use run_command for all workspace file writes instead.",
			}})
			os.Exit(1)
		}
	}
	if mode == "mismatch" {
		sessionID = "conversation-other"
	}
	writeJSON(map[string]any{"event": "init", "conversation_id": sessionID, "init": map[string]any{"conversation_id": sessionID}})
	if mode == "sleep" {
		time.Sleep(30 * time.Second)
		os.Exit(3)
	}
	if mode == "steer" && prompt != "apply the steering message" {
		time.Sleep(30 * time.Second)
		os.Exit(3)
	}
	schemaValue := any(nil)
	if path := flagValue(args, "--json-schema"); path != "" {
		raw, err := os.ReadFile(path)
		if err != nil || json.Unmarshal(raw, &schemaValue) != nil {
			os.Exit(4)
		}
		writeJSON(map[string]any{"event": "step_update", "step_update": map[string]any{"step_index": 1, "step_type": "tool", "state": "ACTIVE", "tool_info": map[string]any{"name": "write_file", "parameters": map[string]any{"path": "x"}}}})
		writeJSON(map[string]any{"event": "step_update", "step_update": map[string]any{"step_index": 1, "step_type": "tool", "state": "DONE", "tool_info": map[string]any{"name": "write_file", "output": "ok"}}})
		writeJSON(map[string]any{"event": "step_update", "step_update": map[string]any{"step_index": 2, "step_type": "agent_response", "state": "ACTIVE", "text_delta": "done"}})
		writeJSON(map[string]any{"event": "step_update", "step_update": map[string]any{"step_index": 2, "step_type": "agent_response", "state": "DONE", "usage": map[string]any{"input_tokens": 2}}})
	}
	structured := any(map[string]any{"answer": "valid"})
	if mode == "repair" && !strings.Contains(prompt, "previous structured output") {
		structured = map[string]any{"wrong": true}
	}
	writeJSON(map[string]any{"event": "result", "conversation_id": sessionID, "result": map[string]any{
		"conversation_id": sessionID, "status": "SUCCESS", "structured_output": structured, "json_schema": schemaValue,
	}})
	os.Exit(0)
}

func writeJSON(value any) {
	_ = json.NewEncoder(os.Stdout).Encode(value)
}

func flagValue(args []string, flag string) string {
	index := slices.Index(args, flag)
	if index < 0 || index+1 >= len(args) {
		return ""
	}
	return args[index+1]
}

func readInvocations(t *testing.T, path string) [][]string {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var result [][]string
	for line := range strings.SplitSeq(strings.TrimSpace(string(raw)), "\n") {
		var args []string
		if err := json.Unmarshal([]byte(line), &args); err != nil {
			t.Fatal(err)
		}
		result = append(result, args)
	}
	return result
}

func assertFlagValue(t *testing.T, args []string, flag, want string) {
	t.Helper()
	if got := flagValue(args, flag); got != want {
		t.Fatalf("%s = %q, want %q in %#v", flag, got, want, args)
	}
}

func waitForInvocations(t *testing.T, path string, want int) {
	t.Helper()
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		if raw, err := os.ReadFile(path); err == nil {
			trimmed := strings.TrimSpace(string(raw))
			if trimmed != "" && strings.Count(trimmed, "\n")+1 >= want {
				return
			}
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatalf("timed out waiting for %d invocation(s)", want)
}

package agy

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"testing"
)

// runHookScript feeds payload to the real hook command (the one Tractor
// provisions into hooks.json) via `sh -c`, exactly as agy would invoke it,
// and parses its stdout decision.
func runHookScript(t *testing.T, payload string) (decision, reason string) {
	t.Helper()
	cmd := exec.Command("sh", "-c", nativeWriteHookCommand())
	cmd.Stdin = strings.NewReader(payload)
	out, err := cmd.Output()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			t.Fatalf("hook command failed: %v (stderr=%s)", err, exitErr.Stderr)
		}
		t.Fatalf("hook command failed: %v", err)
	}
	var parsed struct {
		Decision string `json:"decision"`
		Reason   string `json:"reason"`
	}
	if err := json.Unmarshal(out, &parsed); err != nil {
		t.Fatalf("hook command did not print valid JSON: %v (%q)", err, out)
	}
	return parsed.Decision, parsed.Reason
}

// Payload shapes below mirror the real agy 1.1.15 PreToolUse stdin payload,
// captured empirically by a debug hook during this work (see
// ephemeral/worklog/202608191900-agy-artifact-prevention.md).

func TestNativeWriteHookCommandAllowsInBrainTarget(t *testing.T) {
	payload := `{"artifactDirectoryPath":"/Users/tyler/.gemini/antigravity-cli/brain/abc","conversationId":"abc","toolCall":{"name":"write_to_file","args":{"TargetFile":"/Users/tyler/.gemini/antigravity-cli/brain/abc/note.md","CodeContent":"hi"}}}`
	decision, _ := runHookScript(t, payload)
	if decision != "allow" {
		t.Fatalf("decision = %q, want allow for a target inside artifactDirectoryPath", decision)
	}
}

func TestNativeWriteHookCommandDeniesWorkspaceTarget(t *testing.T) {
	payload := `{"artifactDirectoryPath":"/Users/tyler/.gemini/antigravity-cli/brain/abc","conversationId":"abc","toolCall":{"name":"write_to_file","args":{"TargetFile":"/Users/tyler/workspace/foo.md","CodeContent":"hi"}}}`
	decision, reason := runHookScript(t, payload)
	if decision != "deny" {
		t.Fatalf("decision = %q, want deny for a workspace target outside artifactDirectoryPath", decision)
	}
	if !strings.Contains(reason, nativeWriteHookMarker) {
		t.Fatalf("deny reason = %q, want it to contain %q", reason, nativeWriteHookMarker)
	}
}

func TestNativeWriteHookCommandDeniesWhenArtifactDirectoryMissing(t *testing.T) {
	// A payload that doesn't parse as expected (missing artifactDirectoryPath)
	// must fail closed, never open: it can only ever wrongly deny a write
	// agy would have accepted, never wrongly allow one it would reject.
	decision, _ := runHookScript(t, `{"toolCall":{"name":"write_to_file","args":{"TargetFile":"/workspace/foo.md"}}}`)
	if decision != "deny" {
		t.Fatalf("decision = %q, want deny when artifactDirectoryPath is absent from the payload", decision)
	}
}

func TestNativeWriteHookCommandDeniesEmptyPayload(t *testing.T) {
	decision, _ := runHookScript(t, "")
	if decision != "deny" {
		t.Fatalf("decision = %q, want deny for an empty/unparseable payload", decision)
	}
}

func TestNativeWriteHookCommandDeniesIfAnyTargetEscapesRoot(t *testing.T) {
	// multi_replace_file_content's exact args shape wasn't independently
	// captured live (see worklog); this proves the script's stance if a
	// tool call ever carries more than one TargetFile occurrence: any
	// target outside the root denies the whole call.
	payload := `{"artifactDirectoryPath":"/brain/abc","toolCall":{"name":"multi_replace_file_content","args":{"Edits":[{"TargetFile":"/brain/abc/a.md"},{"TargetFile":"/workspace/b.md"}]}}}`
	decision, _ := runHookScript(t, payload)
	if decision != "deny" {
		t.Fatalf("decision = %q, want deny when any extracted TargetFile lies outside the artifact root", decision)
	}
}

func TestAgyVersionAtLeast(t *testing.T) {
	for _, tc := range []struct {
		actual, min string
		want        bool
	}{
		{"1.1.15", "1.1.15", true},
		{"1.1.16", "1.1.15", true},
		{"1.2.0", "1.1.15", true},
		{"2.0.0", "1.1.15", true},
		{"1.1.14", "1.1.15", false},
		{"1.0.99", "1.1.15", false},
		{"1.10.0", "1.9.0", true}, // numeric, not lexicographic, comparison
		{"1.1", "1.1.15", false},  // shorter actual treated as zero-padded
		{"1.1.15.2", "1.1.15", true},
	} {
		got, err := agyVersionAtLeast(tc.actual, tc.min)
		if err != nil {
			t.Fatalf("agyVersionAtLeast(%q, %q) unexpected error: %v", tc.actual, tc.min, err)
		}
		if got != tc.want {
			t.Errorf("agyVersionAtLeast(%q, %q) = %v, want %v", tc.actual, tc.min, got, tc.want)
		}
	}
}

func TestAgyVersionAtLeastRejectsUnparseableVersions(t *testing.T) {
	for _, actual := range []string{"", "unknown-build", "v1.1.15-beta", "1.1.x"} {
		if _, err := agyVersionAtLeast(actual, minSupportedAgyVersion); err == nil {
			t.Errorf("agyVersionAtLeast(%q, ...) = nil error, want a parse error for an unparseable version", actual)
		}
	}
}

func TestEnsureNativeWriteHookConcurrentProvisioningLosesNoUpdates(t *testing.T) {
	home := t.TempDir()
	if err := os.MkdirAll(filepath.Join(home, ".gemini", "config"), 0o755); err != nil {
		t.Fatal(err)
	}

	const otherWriters = 8
	var wg sync.WaitGroup
	errs := make(chan error, otherWriters+4)

	// Simulate other concurrent writers (other Tractor processes / tools)
	// each adding their own distinct top-level key via the same lock +
	// atomic-rename discipline ensureNativeWriteHook uses, racing against
	// several concurrent ensureNativeWriteHook calls.
	addForeignKey := func(name string) error {
		unlock, err := lockHooksConfig(home)
		if err != nil {
			return err
		}
		defer unlock()
		path := hooksConfigPath(home)
		doc := map[string]json.RawMessage{}
		if raw, err := os.ReadFile(path); err == nil {
			if err := json.Unmarshal(raw, &doc); err != nil {
				return err
			}
		} else if !os.IsNotExist(err) {
			return err
		}
		doc[name] = json.RawMessage(`{"PostToolUse":[]}`)
		encoded, err := json.MarshalIndent(doc, "", "  ")
		if err != nil {
			return err
		}
		return writeFileAtomic(path, append(encoded, '\n'), 0o644)
	}

	for i := 0; i < otherWriters; i++ {
		wg.Add(1)
		name := fmt.Sprintf("other-hook-%d", i)
		go func() {
			defer wg.Done()
			if err := addForeignKey(name); err != nil {
				errs <- err
			}
		}()
	}
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if err := ensureNativeWriteHook(home); err != nil {
				errs <- err
			}
		}()
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatalf("concurrent provisioning error: %v", err)
	}

	raw, err := os.ReadFile(hooksConfigPath(home))
	if err != nil {
		t.Fatal(err)
	}
	var doc map[string]json.RawMessage
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("hooks.json is not valid JSON after concurrent writers: %v (%s)", err, raw)
	}
	if _, ok := doc[tractorHookName]; !ok {
		t.Fatalf("tractor hook missing after concurrent provisioning: %s", raw)
	}
	for i := 0; i < otherWriters; i++ {
		name := fmt.Sprintf("other-hook-%d", i)
		if _, ok := doc[name]; !ok {
			t.Fatalf("concurrent writer's key %q was lost (read-modify-write race): %s", name, raw)
		}
	}
}

